{"path":"server.js","content":"import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const page = readFileSync(new URL('./public/index.html', import.meta.url));

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') {
      return json(res, 200, { status: 'ok' });
    }
    if (req.method === 'GET' && path === '/api/projects') {
      return json(res, 200, listProjects.all());
    }
    if (req.method === 'POST' && path === '/api/projects') {
      let body = '';
      for await (const chunk of req) {
        body += chunk;
        if (body.length > 65536) return json(res, 413, { error: 'Request too large' });
      }
      let input;
      try { input = JSON.parse(body); }
      catch { return json(res, 400, { error: 'Invalid JSON' }); }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, getProject.get(Number(result.lastInsertRowid)));
    }
    const apiMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && apiMatch) {
      const project = getProject.get(Number(apiMatch[1]));
      return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
    }
    if (req.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(page);
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    json(res, 500, { error: 'An unexpected error occurred' });
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
"}

{"path":"public/index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f4f6fa; color: #1b293d; font: 16px system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #d9e0ea; border-radius: 12px; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    .controls { display: flex; gap: 12px; flex-wrap: wrap; }
    input { flex: 1; min-width: 160px; border: 1px solid #8493a8; border-radius: 6px; padding: 12px; font: inherit; }
    button { background: #2257b4; color: white; border: 0; border-radius: 6px; padding: 12px 18px; font: inherit; cursor: pointer; }
    button:disabled { opacity: .6; cursor: wait; }
    :focus-visible { outline: 3px solid #dc8b00; outline-offset: 3px; }
    [role="alert"] { color: #a32323; margin-top: 16px; }
    #projects { margin-top: 28px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid #d9e0ea; padding: 16px 0; }
    .project-row span { overflow-wrap: anywhere; min-width: 0; }
    .project-row button { flex-shrink: 0; }
    @media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.getElementById('app');
    async function request(path, options) {
      const response = await fetch(path, options);
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'Unable to load projects');
      return body;
    }
    function showError(message) {
      let alert = app.querySelector('[role="alert"]');
      if (!alert) {
        alert = document.createElement('p');
        alert.setAttribute('role', 'alert');
        app.append(alert);
      }
      alert.textContent = message;
      alert.hidden = false;
    }
    function addRow(project) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      const open = document.createElement('button');
      open.textContent = 'Open project';
      open.addEventListener('click', () => { location.href = '/projects/' + project.id; });
      row.append(name, open);
      document.getElementById('projects').append(row);
    }
    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        app.innerHTML = '<h1></h1><button id="back">Projects</button>';
        document.getElementById('back').addEventListener('click', () => { location.href = '/'; });
        try {
          const project = await request('/api/projects/' + match[1]);
          app.querySelector('h1').textContent = project.name;
        } catch (error) { showError(error.message); }
        return;
      }
      app.innerHTML = '<h1>Workboard</h1><form><label for="project-name">Project name</label><div class="controls"><input id="project-name" name="name" type="text"><button type="submit">Create project</button></div><p role="alert" hidden></p></form><section id="projects" aria-label="Projects"></section>';
      const form = app.querySelector('form');
      const input = document.getElementById('project-name');
      const button = form.querySelector('button');
      button.disabled = true;
      try {
        for (const project of await request('/api/projects')) addRow(project);
      } catch (error) { showError(error.message); }
      button.disabled = false;
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) { showError('Project name is required'); return; }
        button.disabled = true;
        app.querySelector('[role="alert"]').hidden = true;
        try {
          const project = await request('/api/projects', {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
          });
          addRow(project);
          input.value = '';
          input.focus();
        } catch (error) { showError(error.message); }
        finally { button.disabled = false; }
      });
    }
    render();
  </script>
</body>
</html>
"}

{"path":"test/server.test.js","content":"import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

test('projects validate, retain creation order, and persist across restart', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  let child;
  let base;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, DB_PATH: join(dir, 'projects.sqlite'), PORT: '0' },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    // Discover the ephemeral port without changing the application launch contract.
    // The test uses a small preload to print the bound address.
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  // Use a dynamically imported server and report its listening port via node:http.
  async function launch() {
    const script = `import http from 'node:http';
      const listen = http.Server.prototype.listen;
      http.Server.prototype.listen = function (...args) {
        this.once('listening', () => console.log(this.address().port));
        return listen.apply(this, args);
      };
      await import('./server.js');`;
    child = spawn(process.execPath, ['--input-type=module', '-e', script], {
      env: { ...process.env, DB_PATH: join(dir, 'projects.sqlite'), PORT: '0' },
      stdio: ['ignore', 'pipe', 'inherit'],
    });
    const [chunk] = await once(child.stdout, 'data');
    base = 'http://127.0.0.1:' + chunk.toString().trim();
  }
  async function create(name) {
    return fetch(base + '/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
  }
  try {
    await launch();
    const health = await fetch(base + '/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.equal((await create('   ')).status, 400);
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), []);
    const first = await (await create('  Alpha  ')).json();
    const second = await (await create('Beta')).json();
    assert.equal(first.name, 'Alpha');
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), [first, second]);
    assert.equal((await fetch(base + '/projects/' + first.id)).status, 200);
    await stop();
    await launch();
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await fetch(base + '/api/projects/' + first.id)).json(), first);
  } finally {
    await stop();
    await rm(dir, { recursive: true, force: true });
  }
});
"}

